// Assemble the browser and host halves of dsh-client-ui-solarized-grid.
//
// Inputs : src/tokens.js (generated by build-solarized-tokens.mjs), src/grid.css, src/client-template.js
// Output : lib/client.js (browser bundle), lib/index.js (host half)
//
// Everything else in this repository is authored, not generated: package.json,
// cordis.patch.yml, README/LICENSE/CREDITS/CHANGELOG and install/uninstall.ps1 are the
// published files themselves, so this script only ever writes lib/.
//
//   node tools/build-plugin.mjs [repo-root]
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = process.argv[2] ?? path.join(HERE, '..');
const PKG = 'dsh-client-ui-solarized-grid';

const tokens = fs.readFileSync(path.join(ROOT, 'src', 'tokens.js'), 'utf8').trim();
const grid = fs.readFileSync(path.join(ROOT, 'src', 'grid.css'), 'utf8').trim();
const template = fs.readFileSync(path.join(ROOT, 'src', 'client-template.js'), 'utf8');

const client = template
  .replace('/*__TOKENS__*/', tokens.replace(/^export const SOLARIZED_TOKENS = /, 'const SOLARIZED_TOKENS = '))
  .replace('/*__CSS__*/', JSON.stringify(grid));

fs.mkdirSync(path.join(ROOT, 'lib'), { recursive: true });
fs.writeFileSync(path.join(ROOT, 'lib', 'client.js'), client);
fs.writeFileSync(path.join(ROOT, 'lib', 'index.js'), `/**
 * Host half of ${PKG}.
 *
 * The theme is browser-side: lib/client.js registers the token override layer and injects the
 * grid stylesheet. This row exists only so the Loader mounts the package, which is what makes
 * client-modules serve the bundle.
 */
export const name = ${JSON.stringify(PKG)};

/** No host-side contribution. */
export function apply() {}
`);

console.log(`wrote ${path.join(ROOT, 'lib')}`);
console.log(`client.js: ${fs.statSync(path.join(ROOT, 'lib', 'client.js')).size} bytes`);
